package com.smartresponse.api; import com.smartresponse.domain.*; import com.smartresponse.repository.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/emergencies/{emergencyId}/feedback") public class FeedbackController {private final EmergencyRepository emergencies;private final UserRepository users;private final EmergencyFeedbackRepository feedback;public FeedbackController(EmergencyRepository e,UserRepository u,EmergencyFeedbackRepository f){emergencies=e;users=u;feedback=f;}@PostMapping public ResponseEntity<Void> add(@PathVariable UUID emergencyId,Authentication a,@Valid @RequestBody FeedbackRequest r){Emergency e=emergencies.findById(emergencyId).orElseThrow();AppUser u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();if(!e.getReporterId().equals(u.getId())||e.getStatus()!=EmergencyStatus.RESOLVED)throw new SecurityException("Feedback is allowed only by the reporter after resolution");if(feedback.existsByEmergencyId(emergencyId))throw new IllegalStateException("Feedback already submitted");feedback.save(new EmergencyFeedback(e,u,r.rating(),r.comments()));return ResponseEntity.status(HttpStatus.CREATED).build();}private FeedbackResponse map(EmergencyFeedback f){return new FeedbackResponse(f.getId(),f.getEmergency().getId(),f.getEmergency().getType().name(),f.getRating(),f.getComments(),f.getCreatedAt(),f.getReporter().getFullName());}}
